mapper.select:
/*AdmGroupBasDAO.listAdmGroupBas 어드민그룹기본 목록 조회 */ SELECT A.GROUP_ID /* 그룹아이디 */ , A.GROUP_DV_CD /* 그룹구분코드 */ , A.GROUP_NM /* 그룹명 */ , A.REPST_ORDR /* 표시순서 */ , A.DESC_CTNT /* 설명내용 */ , A.USE_YN /* 사용여부 */ , (SELECT COUNT(GROUP_ID) FROM ADM_GROUP_USER_REL WHERE GROUP_ID = A.GROUP_ID) AS userCount /* 설정 사용자수 */ , A.FRST_REGI_USER_ID /* 최초등록사용자아이디 */ , A.FRST_REGI_TMSP /* 최초등록타임스탬프 */ , A.LAST_CHNG_USER_ID /* 최종변경사용자아이디 */ , A.LAST_CHNG_TMSP /* 최종변경타임스탬프 */ FROM ADM_GROUP_BAS A WHERE 1=1
AND (A.GROUP_ID LIKE CONCAT('%', #{groupIdOrNm}, '%') OR A.GROUP_NM LIKE ('%', #{groupIdOrNm}, '%'))
AND A.GROUP_DV_CD = #{groupDvCd}
ORDER BY A.REPST_ORDR ASC

SELECT COUNT(*) AS totalCount FROM ADM_GROUP_BAS WHERE 1=1
AND (GROUP_ID LIKE CONCAT('%', #{groupIdOrNm}, '%') OR GROUP_NM LIKE ('%', #{groupIdOrNm}, '%'))
AND GROUP_DV_CD = #{groupDvCd}
